// One item per new A2 request (reminders send no video). The worker serves the preview against the
// qa_preview job's media token (D-057). Replace the base URL on import.
const WORKER = 'REPLACE_WITH_WORKER_URL';
const rows = $input.all().filter((item) => item.json.kind === 'REQUEST' && item.json.media);
return rows.map(({ json: row }) => {
  const media = typeof row.media === 'string' ? JSON.parse(row.media) : row.media;
  const shortId = String(row.video_id).slice(0, 8);
  return {
    json: {
      url: `${WORKER}/media/${row.video_id}/${row.version}/${media.job_id}/preview.mp4?t=${media.token}`,
      caption: `Video ${shortId} v${row.version} · preview 720p · ${row.title ?? '?'}`.slice(0, 1024),
    },
  };
});

// One message with buttons per row from preview_approvals_due(), after its video. Telegram text is
// Vietnamese (D-061); QA check names come from the worker in English and are translated here. Notes come back as a reply to this message
// (WF-06 finds the request by the trailing ref). Callback data: a2:<A|R>:<32-hex token>.
const rows = $input.all().filter((item) => typeof item.json.token === 'string');
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
const CHECKS = {
  format: 'định dạng',
  size: 'kích thước',
  duration: 'thời lượng',
  loudness: 'âm lượng',
  subtitles: 'phụ đề',
  'black frames': 'khung hình đen',
  silence: 'im lặng',
};
const clock = (s) => `${Math.floor(s / 60)}:${String(Math.round(s % 60)).padStart(2, '0')}`;
return rows.map(({ json: row }) => {
  const shortId = String(row.video_id).slice(0, 8);
  const media = parse(row.media);
  const cost = Object.entries(parse(row.cost) ?? {})
    .map(([currency, total]) => `${Math.round(total * 100) / 100} ${currency}`)
    .join(', ');
  const header = row.kind === 'REMINDER'
    ? '[AI Video] Nhắc: preview đang chờ duyệt (A2)'
    : '[AI Video] Preview sẵn sàng để duyệt (A2)';
  const qa = media
    ? [
        `QA: ${media.level}${media.duration_seconds ? ` · ${clock(media.duration_seconds)}` : ''}`,
        ...(media.checks ?? [])
          .filter((check) => check.level !== 'PASS')
          .map((check) => `- ${CHECKS[check.name] ?? check.name}: ${check.detail}`),
      ]
    : [];
  const text = [
    header,
    `Video ${shortId} v${row.version} · storyboard vòng ${row.round}/4`,
    `Tiêu đề: ${row.title ?? '?'}`,
    ...qa,
    ...(row.kind === 'REQUEST' ? [`Chi phí đến giờ: ${cost || 'chưa ghi nhận'}`] : []),
    '',
    'Bấm Duyệt để render bản cuối 1080p. Muốn sửa thì trả lời (reply) tin này kèm ghi chú (thành một vòng storyboard mới).',
    `Hết hạn: ${new Date(row.expires_at).toISOString().replace('T', ' ').slice(0, 16)} UTC`,
    `ref:${row.token}`,
  ].join('\n');
  return { json: { text, approve: `a2:A:${row.token}`, reject: `a2:R:${row.token}` } };
});
